"use client";

import { useState } from "react";
import { formatBtcPrice, formatMoney, formatOutcomePrice, formatQuantity, formatUtc } from "../lib/presentation/format";
import type { CompilationDto } from "../lib/presentation/types";
import { StatusPill } from "./status-pill";

function Exact({ value, children }: { readonly value: string | undefined; readonly children: React.ReactNode }): React.JSX.Element { return <dd title={value}>{children}</dd>; }

export function ResultPanels({ result }: { readonly result: CompilationDto | undefined }): React.JSX.Element | null {
  const [segmentsOpen, setSegmentsOpen] = useState(false);
  if (!result) return null;
  if (result.status === "FEASIBLE") return <div className="result-grid"><section className="panel verification success"><div className="panel-heading"><div><p className="eyebrow">EXACT SETTLEMENT VERIFICATION</p><h2>Passed</h2></div><StatusPill value="FEASIBLE" /></div><dl className="metric-list"><div><dt>Worst terminal PnL</dt><Exact value={result.verification?.worstCasePnl}>{result.verification ? formatMoney(result.verification.worstCasePnl) : "—"}</Exact></div><div><dt>Worst settlement state</dt><Exact value={result.verification?.worstCasePrice}>{result.verification ? `${formatBtcPrice(result.verification.worstCasePrice)} · ${result.verification.worstCasePosition}` : "—"}</Exact></div><div><dt>Relevant boundary states</dt><dd>{result.verification?.boundaryStateCount}</dd></div><div><dt>Acquisition premium</dt><Exact value={result.acquisitionCost}>{result.acquisitionCost ? formatMoney(result.acquisitionCost) : "—"}</Exact></div><div><dt>Fee treatment</dt><dd>{result.feeTreatment}</dd></div><div><dt>Depth constraints</dt><dd>Respected</dd></div><div><dt>Book snapshot</dt><dd>{result.freshness[0]?.observedAt ? formatUtc(result.freshness[0].observedAt) : "Unavailable"}</dd></div><div><dt>Freshness</dt><dd>{result.freshness.length ? result.freshness.map((entry) => entry.state).join(", ") : "Unavailable"}</dd></div></dl><p className="scope-warning">Contour verifies terminal settlement payoff. It does not eliminate intra-period liquidation risk, future funding, book changes after this snapshot, incomplete fills, or settlement/oracle risks outside this model.</p></section><section className="panel construction"><div className="panel-heading"><div><p className="eyebrow">CONSTRUCTION</p><h2>Selected positions</h2></div><span className="count">{result.selectedPositions?.length ?? 0}</span></div><div className="position-list">{result.selectedPositions?.map((position) => <article key={`${position.marketId}-${position.side}`} className="position-row"><div><strong>#{position.marketId} · {position.side.toUpperCase()}</strong><p>{position.statement}</p></div><div><span>Quantity</span><strong title={position.quantity}>{formatQuantity(position.quantity)}</strong></div><div><span>Premium</span><strong title={position.acquisitionCost}>{formatMoney(position.acquisitionCost)}</strong></div></article>)}</div><button className="secondary-button" type="button" onClick={() => setSegmentsOpen((open) => !open)}>{segmentsOpen ? "Hide" : "Inspect"} execution segments ({result.executionSegments?.length ?? 0})</button>{segmentsOpen && <div className="segment-table-wrap"><table><thead><tr><th>Market</th><th>Side</th><th>Book price</th><th>Chosen</th><th>Available</th></tr></thead><tbody>{result.executionSegments?.map((segment) => <tr key={`${segment.marketId}-${segment.side}-${segment.bookLevel}`}><td>#{segment.marketId} / L{segment.bookLevel + 1}</td><td>{segment.side.toUpperCase()}</td><td title={segment.bookPrice}>{formatOutcomePrice(segment.bookPrice)}</td><td title={segment.quantity}>{formatQuantity(segment.quantity)}</td><td title={segment.available}>{formatQuantity(segment.available)}</td></tr>)}</tbody></table></div>}</section></div>;
  if (result.status === "ALREADY_SATISFIED") return <section className="panel result-state success"><StatusPill value={result.status} /><h2>Already satisfied</h2><p>The existing terminal exposure meets this constraint. No additional outcome positions are required.</p><strong>Acquisition premium: $0.00</strong></section>;
  if (result.status === "INFEASIBLE") return <section className="panel result-state infeasible"><StatusPill value={result.status} /><h2>No executable contour found</h2><p>{result.infeasibility?.explanation}</p><dl className="metric-list"><div><dt>Reason</dt><dd>{result.infeasibility?.reason}</dd></div><div><dt>Budget</dt><Exact value={result.maximumAcquisitionCost}>{result.maximumAcquisitionCost ? formatMoney(result.maximumAcquisitionCost) : "—"}</Exact></div>{result.infeasibility?.minimumRequiredBudget && <div><dt>Minimum required budget</dt><Exact value={result.infeasibility.minimumRequiredBudget}>{formatMoney(result.infeasibility.minimumRequiredBudget)}</Exact></div>}</dl></section>;
  return <section className="panel result-state error"><StatusPill value={result.status} /><h2>{result.status.replaceAll("_", " ")}</h2><p>{result.explanation ?? result.issues?.join(" · ")}</p></section>;
}
